-- 0003: partner identity, invitations and project-scoped collaboration.
CREATE TABLE partner_accounts(id BIGSERIAL PRIMARY KEY,employee_id BIGINT UNIQUE REFERENCES employees(id) ON DELETE SET NULL,email TEXT NOT NULL UNIQUE CHECK(email=lower(email)),display_name TEXT NOT NULL CHECK(length(btrim(display_name)) BETWEEN 1 AND 120),password_hash TEXT NOT NULL,auth_version INTEGER NOT NULL DEFAULT 1,active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE partner_affiliations(id BIGSERIAL PRIMARY KEY,partner_id BIGINT NOT NULL REFERENCES partner_accounts(id) ON DELETE CASCADE,affiliation TEXT NOT NULL CHECK(affiliation IN ('PARTNER','TEAM_MEMBER')),operational_role TEXT NOT NULL CHECK(operational_role='TEAM_CONTRIBUTOR'),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(partner_id,affiliation));
CREATE TABLE partner_invitations(id BIGSERIAL PRIMARY KEY,email TEXT NOT NULL CHECK(email=lower(email)),display_name TEXT NOT NULL,token_hash TEXT NOT NULL UNIQUE CHECK(token_hash ~ '^[a-f0-9]{64}$'),status TEXT NOT NULL DEFAULT 'PENDING' CHECK(status IN ('PENDING','REDEEMED','REVOKED','EXPIRED')),expires_at TIMESTAMPTZ NOT NULL,created_by TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),redeemed_at TIMESTAMPTZ,revoked_at TIMESTAMPTZ);
CREATE INDEX partner_invitations_email_status_idx ON partner_invitations(email,status);
CREATE TABLE partner_projects(id BIGSERIAL PRIMARY KEY,project_key TEXT NOT NULL UNIQUE CHECK(project_key ~ '^[a-z0-9][a-z0-9._-]{1,79}$'),name TEXT NOT NULL CHECK(length(btrim(name)) BETWEEN 1 AND 160),description TEXT NOT NULL DEFAULT '',status TEXT NOT NULL DEFAULT 'ACTIVE' CHECK(status IN ('ACTIVE','ARCHIVED')),created_by TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE partner_project_members(project_id BIGINT NOT NULL REFERENCES partner_projects(id) ON DELETE CASCADE,partner_id BIGINT NOT NULL REFERENCES partner_accounts(id) ON DELETE CASCADE,granted_by TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),PRIMARY KEY(project_id,partner_id));
CREATE TABLE partner_tasks(id BIGSERIAL PRIMARY KEY,project_id BIGINT NOT NULL REFERENCES partner_projects(id) ON DELETE CASCADE,title TEXT NOT NULL CHECK(length(btrim(title)) BETWEEN 1 AND 180),description TEXT NOT NULL DEFAULT '',status TEXT NOT NULL DEFAULT 'OPEN' CHECK(status IN ('OPEN','CLAIMED','SUBMITTED','ACCEPTED','CHANGES_REQUESTED')),claimed_by BIGINT REFERENCES partner_accounts(id) ON DELETE SET NULL,created_by TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX partner_tasks_project_status_idx ON partner_tasks(project_id,status,created_at DESC);
CREATE TABLE partner_task_submissions(id BIGSERIAL PRIMARY KEY,task_id BIGINT NOT NULL REFERENCES partner_tasks(id) ON DELETE CASCADE,partner_id BIGINT NOT NULL REFERENCES partner_accounts(id) ON DELETE CASCADE,body TEXT NOT NULL CHECK(length(btrim(body)) BETWEEN 1 AND 12000),artifact_url TEXT NOT NULL DEFAULT '',status TEXT NOT NULL DEFAULT 'PENDING' CHECK(status IN ('PENDING','ACCEPTED','CHANGES_REQUESTED')),review_note TEXT NOT NULL DEFAULT '',reviewed_by TEXT NOT NULL DEFAULT '',reviewed_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE partner_proposals(id BIGSERIAL PRIMARY KEY,partner_id BIGINT NOT NULL REFERENCES partner_accounts(id) ON DELETE CASCADE,project_id BIGINT REFERENCES partner_projects(id) ON DELETE SET NULL,title TEXT NOT NULL CHECK(length(btrim(title)) BETWEEN 1 AND 180),rationale TEXT NOT NULL CHECK(length(btrim(rationale)) BETWEEN 1 AND 12000),expected_impact TEXT NOT NULL DEFAULT '',status TEXT NOT NULL DEFAULT 'SUBMITTED' CHECK(status IN ('SUBMITTED','UNDER_REVIEW','ACCEPTED','DECLINED')),review_note TEXT NOT NULL DEFAULT '',reviewed_by TEXT NOT NULL DEFAULT '',reviewed_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX partner_proposals_partner_idx ON partner_proposals(partner_id,created_at DESC);
